ObjC.import("AppKit");
const w=$.NSWorkspace.sharedWorkspace;
const current=w.URLForApplicationToOpenURL($.NSURL.URLWithString("multica://branch-functional-regression"));
let p=null;try{p=ObjC.unwrap(current.path)||null;}catch(e){}
const urls=w.URLsForApplicationsWithBundleIdentifier("ai.multica.desktop");
const paths=[];for(let i=0;i<urls.count;i++)paths.push(ObjC.unwrap(urls.objectAtIndex(i).path));
JSON.stringify({defaultApplicationPath:p,registeredApplications:paths});
